<script setup lang="ts">
import {Link,router,useForm} from '@inertiajs/vue3';import {computed,onMounted,onUnmounted,ref} from 'vue';import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import StatusBadge from '@/Components/StatusBadge.vue';import type {Doctor,ExtractionCandidate,MedicalDocument,Patient} from '@/types';
const props=defineProps<{document:MedicalDocument;doctors:Doctor[];patients:Patient[]}>();
const allowlist=['patient_name','patient_document','birth_date','age','age_at_consultation','sex','issue_date','consultation_date','consultation_time','start_date','end_date','leave_start_date','leave_end_date','days','leave_days','symptoms','medical_reason','diagnosis','treatment','recommendations','observations','doctor_name','doctor_credential','clinic_name','clinic_address'] as const;
const labels:Record<string,string>={patient_name:'Paciente',patient_document:'Documento del paciente',birth_date:'Fecha de nacimiento',age:'Edad',age_at_consultation:'Edad en consulta',sex:'Sexo',issue_date:'Fecha de emisión',consultation_date:'Fecha de consulta',consultation_time:'Hora de consulta',start_date:'Fecha inicial',end_date:'Fecha final',leave_start_date:'Inicio del descanso',leave_end_date:'Fin del descanso',days:'Días',leave_days:'Días de descanso',symptoms:'Síntomas',medical_reason:'Motivo médico',diagnosis:'Diagnóstico',treatment:'Tratamiento',recommendations:'Recomendaciones',observations:'Observaciones',doctor_name:'Profesional',doctor_credential:'Credencial profesional',clinic_name:'Clínica',clinic_address:'Dirección de clínica'};
const raw=props.document.extractions?.[0]?.candidates??{};
const grouped:Record<string,unknown[]>=Object.fromEntries(allowlist.map(field=>[field,[]]));
if(Array.isArray(raw)){for(const candidate of raw as ExtractionCandidate[]){if(candidate?.field&&candidate.field in grouped)grouped[candidate.field].push(candidate);}}else{for(const [field,candidate] of Object.entries(raw)){if(field in grouped)grouped[field].push(...(Array.isArray(candidate)?candidate:[candidate]));}}
const value=(candidate:unknown)=>{if(candidate==null)return '';if(typeof candidate==='object'){const item=candidate as Record<string,unknown>;return String(item.value??item.text??item.content??'');}return String(candidate)};
const fields=allowlist.filter(field=>grouped[field].length||Object.prototype.hasOwnProperty.call(props.document.confirmed_fields??{},field));
const seed=Object.fromEntries(fields.map(field=>[field,props.document.confirmed_fields?.[field]??value(grouped[field][0])]));
const form=useForm({fields:seed as Record<string,string|null>,doctor_id:props.document.doctor?.id??'',patient_id:props.document.patient?.id??'',approve:false});
const canMutate=computed(()=>['REVIEW_REQUIRED','READY'].includes(props.document.status));const canIssue=computed(()=>props.document.status==='READY');
const save=(approve:boolean)=>{if(!canMutate.value)return;form.approve=approve;form.put(route('admin.documents.confirm',props.document.id),{preserveScroll:true});};
const confirmAction=ref<'issue'|null>(null);const issue=()=>router.post(route('admin.documents.issue',props.document.id),{},{preserveScroll:true,onSuccess:()=>confirmAction.value=null});
let poll:number|undefined;onMounted(()=>{if(props.document.status==='PROCESSING')poll=window.setInterval(()=>router.reload({only:['document']}),2000)});onUnmounted(()=>window.clearInterval(poll));
</script>
<template><AdminLayout :title="`Revisión · ${document.public_code||document.original_filename}`" eyebrow="Documentos / Revisión"><PageMeta title="Revisar documento" noindex/><section class="admin-content review-content"><div class="workflow-scroll"><div class="workflow"><div class="done"><i>1</i><span>Carga</span></div><b></b><div :class="{done:document.status!=='PROCESSING'}"><i>2</i><span>Extracción</span></div><b></b><div :class="{active:['REVIEW_REQUIRED','READY'].includes(document.status),done:['READY','ISSUED','REVOKED','REPLACED'].includes(document.status)}"><i>3</i><span>Validación</span></div><b></b><div :class="{done:['READY','ISSUED','REVOKED','REPLACED'].includes(document.status)}"><i>4</i><span>Aprobación</span></div><b></b><div :class="{done:['ISSUED','REVOKED','REPLACED'].includes(document.status)}"><i>5</i><span>Emisión</span></div></div></div><div class="review-top"><div><StatusBadge :status="document.status"/><p>Archivo original: <strong class="code-wrap">{{ document.original_filename }}</strong></p></div><div class="action-row"><a class="button button--outline-small" :href="route('admin.documents.download',{document:document.id,version:'original'})">Descargar original</a><a v-if="document.issued_at" class="button button--outline-small" :href="route('admin.documents.download',{document:document.id,version:'issued'})">Descargar emitido</a><button v-if="canIssue" class="button button--admin" type="button" @click="confirmAction='issue'">Emitir documento</button></div></div><div v-if="document.status==='PROCESSING'" class="panel process-state" role="status"><h2>Procesando documento</h2><p>La extracción se actualiza automáticamente. No hay mutaciones disponibles hasta que termine.</p></div><div v-if="document.status==='FAILED'" class="warning-box"><strong>El procesamiento falló</strong><p class="code-wrap">{{ document.processing_metadata?.error||'El servidor no proporcionó un detalle público.' }}</p><div class="action-row"><Link class="button button--outline-small" :href="route('admin.documents.index',{status:'FAILED'})">Ver documentos fallidos</Link><Link class="button button--admin" :href="route('admin.documents.create')">Cargar otro PDF</Link></div></div><div v-if="document.inconsistencies?.length" class="warning-box"><strong>Observaciones de consistencia</strong><ul><li v-for="(item,index) in document.inconsistencies" :key="index" class="code-wrap">{{ typeof item==='string'?item:JSON.stringify(item) }}</li></ul></div><form v-if="canMutate" class="review-grid" @submit.prevent="save(false)"><div class="panel form-panel"><div class="panel-head"><div><p class="kicker">Datos extraídos</p><h2>Validación de campos</h2><p>El valor OCR se conserva como evidencia y el campo editable representa el valor confirmado.</p></div><span v-if="document.extractions?.[0]?.quality_score" class="quality">Calidad {{ document.extractions[0].quality_score }}</span></div><div v-if="fields.length" class="form-grid"><div v-for="field in fields" :key="field" class="field"><label :for="`field-${field}`">{{ labels[field] }}</label><textarea v-if="['symptoms','medical_reason','diagnosis','treatment','recommendations','observations'].includes(field)" :id="`field-${field}`" v-model="form.fields[field]" rows="3" maxlength="2000"></textarea><input v-else :id="`field-${field}`" v-model="form.fields[field]" maxlength="2000"><small class="ocr-value"><b>OCR:</b> {{ grouped[field].map(value).filter(Boolean).join(' | ')||'Sin candidato' }}</small><span class="field-error">{{ form.errors[`fields.${field}`] }}</span></div></div><p v-else>No se recibieron candidatos permitidos. Seleccione las relaciones y guarde para continuar.</p><div class="form-actions"><button class="button button--outline-small" type="submit" :disabled="form.processing">Guardar revisión</button><button class="button button--admin" type="button" :disabled="form.processing" @click="save(true)">Aprobar revisión</button></div></div><aside class="panel review-aside"><div class="field"><label for="patient">Paciente vinculado</label><select id="patient" v-model="form.patient_id"><option value="">Sin vincular</option><option v-for="patient in patients" :key="patient.id" :value="patient.id">{{ patient.last_name }}, {{ patient.first_name }}</option></select></div><div class="field"><label for="doctor">Profesional vinculado</label><select id="doctor" v-model="form.doctor_id"><option value="">Sin vincular</option><option v-for="doctor in doctors" :key="doctor.id" :value="doctor.id">{{ doctor.professional_name||`${doctor.last_name}, ${doctor.first_name}` }}</option></select></div><div class="version-info"><strong>Versiones privadas</strong><p>Original inmutable disponible.</p><p v-if="document.issued_at">Versión emitida disponible desde {{ document.issued_at }}.</p></div><Link class="back-admin" :href="route('admin.documents.index')">← Volver a documentos</Link></aside></form><div v-if="confirmAction==='issue'" class="confirm-panel panel" role="dialog" aria-modal="true" aria-labelledby="issue-title"><h2 id="issue-title">Confirmar emisión</h2><p>Se generará la versión emitida y su código de verificación.</p><div class="form-actions"><button class="button button--outline-small" type="button" @click="confirmAction=null">Cancelar</button><button class="button button--admin" type="button" @click="issue">Confirmar emisión</button></div></div></section></AdminLayout></template>
